{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "IAM policy attached directly to a user",
      "resource": "aws_iam_user_policy_attachment.privesc15-PassExistingRoleToNewLambdaThenInvoke-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "The managed policy is attached directly to an IAM user, making access governance and privilege removal more difficult. Assigning the policy through a group provides centralized and more auditable permission management."
    }
  ],
  "patched_code": "resource "aws_iam_group" "privesc15-PassExistingRoleToNewLambdaThenInvoke-group" {
  name = "${aws_iam_user.privesc15-PassExistingRoleToNewLambdaThenInvoke-user.name}-group"
}

resource "aws_iam_group_membership" "privesc15-PassExistingRoleToNewLambdaThenInvoke-membership" {
  name = "${aws_iam_user.privesc15-PassExistingRoleToNewLambdaThenInvoke-user.name}-group-membership"
  users = [
    aws_iam_user.privesc15-PassExistingRoleToNewLambdaThenInvoke-user.name
  ]
  group = aws_iam_group.privesc15-PassExistingRoleToNewLambdaThenInvoke-group.name
}

resource "aws_iam_group_policy_attachment" "privesc15-PassExistingRoleToNewLambdaThenInvoke-user-attach-policy" {
  group      = aws_iam_group.privesc15-PassExistingRoleToNewLambdaThenInvoke-group.name
  policy_arn = aws_iam_policy.privesc15-PassExistingRoleToNewLambdaThenInvoke.arn
}
",
  "fix_summary": "Replaced the direct user policy attachment with a group policy attachment and added the existing user to that group. The same managed policy remains assigned while access management is centralized through the IAM group."
}
